    "# backend/toko/tests/test_pesanan.py\nimport pytest\nfrom django.contrib.auth.models import User\nfrom rest_framework.test import APIClient\nfrom toko.models import Kategori, Produk\n\n@pytest.fixture\ndef kasir_client(db):\n    c = APIClient()\n    c.force_authenticate(User.objects.create_user('kasir1', password='x'))\n    return c\n\n@pytest.fixture\ndef kopi(db):\n    return Produk.objects.create(kategori=Kategori.objects.create(nama='Biji'), nama='Kopi Gayo', harga=28000, stok=3)\n\ndef test_pesanan_mengurangi_stok_dan_hitung_total(kasir_client, kopi):\n    r = kasir_client.post('/api/pesanan/', {'item': [{'produk': kopi.id, 'jumlah': 2}]}, format='json')\n    assert r.status_code == 201\n    assert r.data['total'] == '56000.00'\n    kopi.refresh_from_db()\n    assert kopi.stok == 1\n\ndef test_stok_kurang_ditolak(kasir_client, kopi):\n    r = kasir_client.post('/api/pesanan/', {'item': [{'produk': kopi.id, 'jumlah': 5}]}, format='json')\n    assert r.status_code == 400\n    kopi.refresh_from_db()\n    assert kopi.stok == 3            # tidak berubah karena rollback\n\ndef test_kasir_tidak_boleh_ubah_produk(kasir_client, kopi):\n    assert kasir_client.patch(f'/api/produk/{kopi.id}/', {'harga': 1}).status_code == 403\n\n# frontend/e2e/pesanan.spec.ts (Playwright)\n# test('kasir membuat pesanan', async ({ page }) => {\n#   await page.goto('/login');\n#   await page.getByLabel('Username').fill('kasir1');\n#   await page.getByLabel('Password').fill('demo1234');\n#   await page.getByRole('button', { name: 'Masuk' }).click();\n#   await page.getByLabel('Cari produk').fill('gayo');\n#   await page.getByRole('button', { name: 'Tambah Kopi Gayo' }).click();\n#   await page.getByRole('button', { name: 'Simpan pesanan' }).click();\n#   await expect(page.getByRole('status')).toContainText('Pesanan #');\n# });",
    "$ pytest -q\n...                                                     [100%]\n3 passed in 0.84s",
